    for (long b = 0; b < nblocks; b++) {
        long lo = b * SAXPY_BLOCK;
        long hi = lo + SAXPY_BLOCK;
        if (hi > n) hi = n;
        const double *restrict xb = x + lo;
        double *restrict yb = y + lo;
        long len = hi - lo;
        for (int r = 0; r < reps; r++) {
            #pragma omp simd
            for (long i = 0; i < len; i++)
                yb[i] = a * xb[i] + yb[i];
        }
    }
}
/* === KERNEL END === */

