#include "common.h"
#include <omp.h>

/* === KERNEL BEGIN === */
static void kernel(int n, int steps, double *u, double *v) {
    #pragma omp parallel firstprivate(u, v)
    {
        for (int t = 0; t < steps; t++) {
            #pragma omp for schedule(static)
            for (int i = 1; i < n - 1; i++) {
                const double *restrict uc = u + (long)i * n;
                const double *restrict uu = u + (long)(i - 1) * n;
                const double *restrict ud = u + (long)(i + 1) * n;
                double *restrict vc = v + (long)i * n;
                #pragma omp simd
                for (int j = 1; j < n - 1; j++)
                    vc[j] = 0.2 * (uc[j] + uu[j] + ud[j] + uc[j - 1] + uc[j + 1]);
            }
            /* implicit barrier above: sweep t complete before sweep t+1 */
            double *tmp = u; u = v; v = tmp;   /* each thread swaps its private copies identically */
        }
        /* After an odd number of sweeps the newest data is in the caller's v:
         * copy it back so the caller always reads the result from u. */
        if (steps % 2 == 1) {
            long nn = (long)n * n;
            #pragma omp for schedule(static)
            for (long k = 0; k < nn; k++) v[k] = u[k];
        }
    }
}
/* === KERNEL END === */

