                       zr0 * zr0 + zi0 * zi0 <= 4.0 &&
                       zr1 * zr1 + zi1 * zi1 <= 4.0) {
                    double t0 = zr0 * zr0 - zi0 * zi0 + cr0;
                    double t1 = zr1 * zr1 - zi1 * zi1 + cr1;
                    zi0 = 2.0 * zr0 * zi0 + ci;
                    zi1 = 2.0 * zr1 * zi1 + ci;
                    zr0 = t0;
                    zr1 = t1;
                    k++;
